// Observer-only policy prototype: no browser/game imports or private telemetry.
// Geometry: normalized 550x450 canvas px, NOT CSS px or world px.
// Motion: measured canvas px/s. All timestamps/durations: monotonic ms.
export const LIMITS = Object.freeze({ runMs: 360000, calibrationMs: 60000, gapMs: 750 });

export function worldToCanvas(worldPx, publicZoom) {
  if (!(publicZoom >= 0.5 && publicZoom <= 1.5)) throw Error('Unverified public zoom');
  return worldPx * publicZoom;
}

export function cssToCanvas(point, canvasCssBounds) {
  return {
    x: ((point.x - canvasCssBounds.x) / canvasCssBounds.width) * 550,
    y: ((point.y - canvasCssBounds.y) / canvasCssBounds.height) * 450,
  };
}

export function wallReserve({
  maxSpeedCanvasPxPerS,
  brakingCanvasPx,
  silhouetteRadiusCanvasPx,
  captureStartMs,
  inputAckMs,
  nextObservationBudgetMs,
  fitErrorCanvasPx,
}) {
  const values = [
    maxSpeedCanvasPxPerS,
    brakingCanvasPx,
    silhouetteRadiusCanvasPx,
    captureStartMs,
    inputAckMs,
    nextObservationBudgetMs,
    fitErrorCanvasPx,
  ];
  if (
    values.some((v) => !Number.isFinite(v)) ||
    inputAckMs < captureStartMs ||
    maxSpeedCanvasPxPerS < 0 ||
    brakingCanvasPx < 0 ||
    nextObservationBudgetMs < 0
  ) {
    throw Error('Need measured motion, braking, image age and uncertainty');
  }
  // Worst-case oldest-image age, including screenshot, analysis and input ack.
  const staleTravel =
    (maxSpeedCanvasPxPerS * (inputAckMs - captureStartMs + nextObservationBudgetMs)) / 1000;
  return silhouetteRadiusCanvasPx + brakingCanvasPx + staleTravel + fitErrorCanvasPx;
}

function bbox(o, halo = 0) {
  const [x, y, w, h] = o.box;
  return [x - halo, y - halo, x + w + halo, y + h + halo];
}
function intersects(a, b) {
  return a[0] < b[2] && a[2] > b[0] && a[1] < b[3] && a[3] > b[1];
}

// Every pickup route, nearby or fallback, uses the same single object partition
// and the same ambiguity/path checks. Unknowns never become pickup fallback.
export function collectionCandidate(objects, { from = { x: 275, y: 225 }, playerExtentPx }) {
  if (!Number.isFinite(playerExtentPx)) return null;
  const hazards = objects.filter((o) => o.label === 'actor' || o.label === 'unknown');
  const candidates = objects
    .filter((o) => o.label === 'pickup')
    .filter((p) => {
      // Conservative swept segment AABB. Overrejecting a route is recorded as a
      // collection limit; it cannot silently override combat or traverse a threat.
      const path = [
        Math.min(from.x, p.x) - playerExtentPx,
        Math.min(from.y, p.y) - playerExtentPx,
        Math.max(from.x, p.x) + playerExtentPx,
        Math.max(from.y, p.y) + playerExtentPx,
      ];
      return !hazards.some((o) => intersects(path, bbox(o, playerExtentPx)));
    });
  return (
    candidates.sort(
      (a, b) => Math.hypot(a.x - from.x, a.y - from.y) - Math.hypot(b.x - from.x, b.y - from.y),
    )[0] ?? null
  );
}

export class IntentState {
  constructor(playStartMs) {
    this.playStartMs = playStartMs;
    this.mode = 'calibration';
    this.intent =
      'Measure screen motion, capture/input latency and visible boundary; ordinary public controls only';
    this.transit = null;
    this.lastCaptureEndMs = null;
    this.coord = null;
    this.stopReason = null;
  }
  stop(reason) {
    this.mode = 'stopped';
    this.stopReason = reason;
    this.intent =
      'Release every input, request public Paused, verify actual dialog, finalize owned video and clean up';
    return { keys: [], fire: false, pauseReview: true, reason };

